// What the driver says when a dispatch is refused.
//
// Composed from the numbers, NOT generated by the model. That is a
// deliberate limitation and the reason for it is the same one that keeps
// the refusal itself out of the prompt: this line has to agree with
// driver_settlements exactly. A generated sentence can round $1,840 to
// "about two grand", or say "a couple of weeks" when the table says nine
// days, and then the dispatcher is holding two versions of one fact with
// nothing to say which is true. The conversation that follows is the
// model's; this first line is the database speaking in the driver's voice.
//
// Wording varies by driver so the same person sounds like themselves and
// two different drivers do not answer with the same sentence. Selected by
// a hash of the driver id -- stable for the life of that driver, the same
// technique brokerChat uses for its per-posting ceiling.

import { REASONS } from '../../constants/availabilityReasons.js'

function hashPick(id, n) {
  let h = 2166136261
  const s = String(id)
  for (let i = 0; i < s.length; i += 1) {
    h ^= s.charCodeAt(i)
    h = Math.imul(h, 16777619)
  }
  return (h >>> 0) % n
}

function money(n) {
  return `$${Math.abs(n ?? 0).toLocaleString('en-US')}`
}

const UNPAID = [
  (a) => `I am not taking another load until I am paid. ${money(a.owedUsd)} still owed, oldest one is ${a.daysOverdue} days past due.`,
  (a) => `Sorry, no. You still owe me ${money(a.owedUsd)} across ${a.unpaidCount} settlement${a.unpaidCount === 1 ? '' : 's'} and the oldest is ${a.daysOverdue} days out. Settle that and I will roll.`,
  (a) => `Not until that ${money(a.owedUsd)} hits my account. I have been waiting ${a.daysOverdue} days on the oldest one.`,
]

const OUT_OF_HOURS = [
  (a) => `My eleven are gone. I cannot move this truck until I have had my ten off -- that is the law, not a mood.`,
  (a) => `I am at zero on drive time. Paper says eleven hours, I have driven every one of them. Ten off and I am yours.`,
  (a) => `No. My clock is at zero -- forty-nine CFR three ninety-five says I stop here, and so do I.`,
]

const QUIT = [
  () => 'I do not run for you any more.',
  () => 'I have moved on. Still want what I was owed.',
]

const BY_REASON = {
  [REASONS.UNPAID]: UNPAID,
  [REASONS.OUT_OF_HOURS]: OUT_OF_HOURS,
  [REASONS.QUIT]: QUIT,
}

// Returns null for a reason with nothing to say, so a caller that adds a
// new reason without a line here posts nothing rather than posting
// 'undefined' into a person's conversation.
export function refusalLine({ driverId, reason, ...args }) {
  const options = BY_REASON[reason]
  if (!options) return null
  return options[hashPick(driverId, options.length)]({ ...args })
}

export { REASONS }
